  ringGrad.addColorStop(0.5,`rgba(255,160,40,${(0.6*bAlpha).toFixed(3)})`);
  ringGrad.addColorStop(0.7,`rgba(255,120,20,${(0.35*bAlpha).toFixed(3)})`);
